    print("The first board's last layer, with a light source switched on.")
    print("pta_board_chain.py's networks and tile at version 2.  Five networks a kind, five draws.")
    heads = (f"  {'':<48}" + "".join(f"{w:>36}" for w in WORKLOADS) + "\n"
             + f"  {'':<48}" + "".join(f"{k:>18}" for w in WORKLOADS for k in KINDS))

